import{_ as t,o as a,c as l,a8 as i}from"./chunks/framework.D570mCLF.js";const p=JSON.parse('{"title":"🏷️ Dialog Labels Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"additional/labels.md","filePath":"additional/labels.md"}'),o={name:"additional/labels.md"};function s(n,e,r,d,h,c){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="🏷️-dialog-labels-configuration" tabindex="-1">🏷️ Dialog Labels Configuration <a class="header-anchor" href="#🏷️-dialog-labels-configuration" aria-label="Permalink to &quot;🏷️ Dialog Labels Configuration&quot;">​</a></h1><h3 id="✨-overview" tabindex="-1">✨ Overview <a class="header-anchor" href="#✨-overview" aria-label="Permalink to &quot;✨ Overview&quot;">​</a></h3><p>Labels are powerful tools to clean up dialog interfaces or force specific behaviors when Home Assistant groups different entities under the same device. They are applied directly through the Home Assistant UI (in the &quot;Labels&quot; section).</p><h2 id="🛠️-available-labels" tabindex="-1">🛠️ Available Labels <a class="header-anchor" href="#🛠️-available-labels" aria-label="Permalink to &quot;🛠️ Available Labels&quot;">​</a></h2><h3 id="_1-dialog-hidden" tabindex="-1">1. <code>Dialog Hidden</code> <a class="header-anchor" href="#_1-dialog-hidden" aria-label="Permalink to &quot;1. `Dialog Hidden`&quot;">​</a></h3><p>This label is used to keep the interface clean and focused only on relevant information.</p><ul><li><strong>Usage:</strong> Apply this label to any entity (sensor, switch, etc.) that is part of a device but that you <strong>do not want to show</strong> inside the Material Dialog.</li><li><strong>Example:</strong> You have a motion sensor that also exposes technical or diagnostic entities that you don&#39;t need in the daily popup.</li></ul><h3 id="_2-template" tabindex="-1">2. <code>Template</code> <a class="header-anchor" href="#_2-template" aria-label="Permalink to &quot;2. `Template`&quot;">​</a></h3><p>This label resolves display issues when a dialog shows unrelated entities.</p><ul><li><strong>Usage:</strong> Apply this label when the dialog refers to a Home Assistant <strong>Helper</strong> or a &quot;template&quot; entity.</li><li><strong>Why use it:</strong> If a Home Assistant device groups many entities that have no direct logical relationship, the dialog might appear cluttered. The <code>Template</code> label instructs the component to handle the display in isolation, optimizing the layout for that specific entity type.</li></ul><h2 id="📝-how-to-apply-labels" tabindex="-1">📝 How to Apply Labels <a class="header-anchor" href="#📝-how-to-apply-labels" aria-label="Permalink to &quot;📝 How to Apply Labels&quot;">​</a></h2><p>You can manage these labels directly in Home Assistant by following these steps:</p><ol><li>Go to <strong>Settings</strong> &gt; <strong>Devices &amp; Services</strong>.</li><li>Select the <strong>Entities</strong> tab or navigate to the specific device.</li><li>Click on the entity you wish to modify.</li><li>Click the <strong>Settings</strong> (gear) icon.</li><li>In the <strong>Labels</strong> field, add one of the two labels: <ul><li><code>Dialog Hidden</code></li><li><code>Template</code></li></ul></li><li>Save the changes. The Material Dialog will update automatically on the next opening.</li></ol><h2 id="💡-practical-examples" tabindex="-1">💡 Practical Examples <a class="header-anchor" href="#💡-practical-examples" aria-label="Permalink to &quot;💡 Practical Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Use Case</th><th style="text-align:left;">Label to Use</th><th style="text-align:left;">Result</th></tr></thead><tbody><tr><td style="text-align:left;">Hiding the &quot;Battery Voltage&quot; sensor of a remote</td><td style="text-align:left;"><code>Dialog Hidden</code></td><td style="text-align:left;">The dialog will only show the main buttons/state, hiding the voltage.</td></tr><tr><td style="text-align:left;">Configuring a sensor created via YAML or Helper</td><td style="text-align:left;"><code>Template</code></td><td style="text-align:left;">The dialog will optimize the view, avoiding showing random related entities.</td></tr></tbody></table><hr><div class="info custom-block"><p class="custom-block-title">⚠️ Important Note</p><p>Make sure the label text is written exactly as shown (case-sensitive), otherwise the system will not be able to recognize them correctly.</p></div>',17)])])}const u=t(o,[["render",s]]);export{p as __pageData,u as default};
